    private void chooseGame(){if(sheet!=null)sheet.dismiss();new AlertDialog.Builder(this).setTitle("A little playtime").setItems(new String[]{"Follow my finger · stroke the screen","Peekaboo · hide then show your face","Reaction game · tap when I smile","Stop playing"},(d,index)->{game="";main.removeCallbacks(gameReady);reactionAt=0;peekSeen=false;peekLeftAt=0;conversation.cancelSocial();if(index==0){game="finger";showCoverStatus("Slide your finger across my face. I will follow.");}else if(index==1){game="peek";showCoverStatus("Show your face, hide for a moment, then peek back!");if(!trackingWanted){trackingWanted=true;startCamera();}}else if(index==2){game="reaction";showCoverStatus("Wait for my smile, then tap!");face.mood(PetFaceView.Mood.IDLE);main.postDelayed(gameReady,1500+(long)(Math.random()*2500));}else showCoverStatus("Ready when you are.");}).setNegativeButton("Close",null).show();}
