    private void chooseSocial(){if(sheet!=null)sheet.dismiss();if(getSystemService(KeyguardManager.class).isDeviceLocked()){status.setText("Unlock Android to choose social mode.");return;}new AlertDialog.Builder(this).setTitle("How sociable should I be?").setItems(new String[]{"Quiet · wait for you","Friendly · one hello this session","Sociable · occasional little conversations"},(dialog,index)->{social.mode(PetSocial.Mode.values()[index]);conversation.cancelSocial();status.setText(index==0?"Quiet company": "Social mode ready · enable local tracking to notice people");if(index>0)new AlertDialog.Builder(this).setTitle("Gentle company").setMessage("I only start a conversation when one person is present, during 8am–10pm, and while you are not talking or playing music. At most twice an hour, with at least 20 minutes between. Say ‘not now’ or ignore a starter to pause them for this session. Names and face registration are not active yet.").setPositiveButton("Got it",null).show();}).setNegativeButton("Close",null).show();}
    private void authenticateOwner(){if(ownerAuthenticating||!visible)return;if(getSystemService(KeyguardManager.class).isDeviceLocked()){status.setText("Unlock Android before entering owner mode.");return;}conversation.stop();ownerAuthenticating=true;ownerCancellation=new CancellationSignal();android.hardware.biometrics.BiometricPrompt.Builder builder=new android.hardware.biometrics.BiometricPrompt.Builder(this).setTitle("Use your private JARVIS tools").setSubtitle("Owner mode ends when you leave pet mode or lock Android");if(Build.VERSION.SDK_INT>=30)builder.setAllowedAuthenticators(android.hardware.biometrics.BiometricManager.Authenticators.BIOMETRIC_STRONG|android.hardware.biometrics.BiometricManager.Authenticators.DEVICE_CREDENTIAL);else if(Build.VERSION.SDK_INT>=29)builder.setDeviceCredentialAllowed(true);else builder.setNegativeButton("Cancel",getMainExecutor(),(d,w)->ownerCancellation.cancel());builder.build().authenticate(ownerCancellation,getMainExecutor(),new android.hardware.biometrics.BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(android.hardware.biometrics.BiometricPrompt.AuthenticationResult result){ownerAuthenticating=false;if(visible){conversation.ownerMode(true);wakeWanted=true;resting=false;startWake();sensorStatus();}else ownerPending=true;}@Override public void onAuthenticationError(int code,CharSequence error){ownerAuthenticating=false;if(visible)startWake();}});}
    private void chooseVoice(){if(sheet!=null)sheet.dismiss();String[] names={"Heart · warm & friendly","Bella · bright & playful","Puck · lively companion","Daniel · classic JARVIS"},ids={"af_heart","af_bella","am_puck","bm_daniel"};new AlertDialog.Builder(this).setTitle("Choose this pet's voice").setItems(names,(dialog,index)->{getPreferences(MODE_PRIVATE).edit().putString("voice",ids[index]).apply();status.setText(names[index]+" selected for this pet");new AlertDialog.Builder(this).setTitle(names[index]).setMessage("This changes only pet speech. Normal JARVIS keeps its existing voice.").setNegativeButton("Done",null).setPositiveButton("Hear a sample",(d,w)->{conversation.stop();if(!CompanionClient.enrolled(this,origin)){status.setText("Connect companion access first to hear a sample.");startWake();}else{previewPlaying=true;conversation.previewVoice();}}).show();}).setNegativeButton("Close",null).show();}
    private void customize(){if(sheet!=null)sheet.dismiss();String[] choices={"Mint eyes","Amber eyes","Lilac eyes","Automatic display layout","Compact / cover layout","Tabletop layout","Full-screen layout","Automatic camera","Inner / front camera","Outer / rear camera"};new AlertDialog.Builder(this).setTitle("Make it yours").setItems(choices,(d,index)->{if(index<3){int[] colors={0xffa9e4d5,0xffe7c58f,0xffbaade8};getPreferences(MODE_PRIVATE).edit().putInt("color",colors[index]).apply();appearance();}else if(index<7){String[] modes={"auto","cover","desk","full"};layout=modes[index-3];getPreferences(MODE_PRIVATE).edit().putString("layout",layout).apply();reflow();}else{String[] cameras={"auto","front","back"};getPreferences(MODE_PRIVATE).edit().putString("camera",cameras[index-7]).apply();if(trackingWanted)restartCamera();}}).setNegativeButton("Done",null).show();}
    private void appearance(){WindowManager.LayoutParams attributes=getWindow().getAttributes();attributes.screenBrightness=dim||lowBattery||deskMode==PetDesk.Mode.BEDTIME?.1f:.55f;getWindow().setAttributes(attributes);face.style(getPreferences(MODE_PRIVATE).getInt("color",0xffa9e4d5),dim||lowBattery||deskMode==PetDesk.Mode.BEDTIME);if(camera!=null)camera.powerSaving(dim||lowBattery||deskMode==PetDesk.Mode.BEDTIME);}
    private final Runnable tick=new Runnable(){public void run(){if(!visible)return;Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int percent=-1;boolean charging=false;if(battery!=null){int scale=battery.getIntExtra(BatteryManager.EXTRA_SCALE,0);if(scale>0)percent=Math.round(battery.getIntExtra(BatteryManager.EXTRA_LEVEL,0)*100f/scale);charging=battery.getIntExtra(BatteryManager.EXTRA_PLUGGED,0)!=0;}boolean thermal=Build.VERSION.SDK_INT>=29&&getSystemService(PowerManager.class).getCurrentThermalStatus()>=PowerManager.THERMAL_STATUS_SEVERE;boolean saving=percent>=0&&percent<=10&&!charging||thermal;if(saving!=lowBattery){lowBattery=saving;appearance();if(saving){stopCamera();conversation.stop();status.setText("Power saving · sensors paused");showCoverStatus(thermal?"Phone is warm · dimmed and sensors paused":"Low battery · dimmed and sensors paused");}else{getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(trackingWanted)startCamera();startWake();}}if(conversation.ownerMode()&&conversation.waitingForWake()&&!getSystemService(KeyguardManager.class).isDeviceLocked())activityFeed.poll();if(focusUntil>0&&System.currentTimeMillis()>=focusUntil){focusUntil=0;getPreferences(MODE_PRIVATE).edit().remove("focusUntil").apply();face.react(PetReactions.Cue.SMILE);showCoverStatus("Focus finished · time for a little break");}clock.setText(android.text.format.DateFormat.format("HH:mm",new java.util.Date())+(percent<0?"":"  "+percent+"%"));main.postDelayed(this,15000);}};
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==196){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)startWake();if(checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)startCamera();else showCoverStatus("Camera permission is off · voice still works");return;}if(grants.length==0||grants[0]!=PackageManager.PERMISSION_GRANTED){status.setText("Permission stays off. You can change it in Android settings.");return;}if(request==191){trackingWanted=true;startCamera();}else if(request==190){toggleTalk();}else if(request==192||request==196){wakeWanted=true;startWake();if(trackingWanted)startCamera();}}
    @Override protected void onStart(){super.onStart();lifecycle.handleLifecycleEvent(Lifecycle.Event.ON_START);folding.addWindowLayoutInfoListener(this,getMainExecutor(),folds);}
    @Override protected void onResume(){super.onResume();lifecycle.handleLifecycleEvent(Lifecycle.Event.ON_RESUME);visible=true;social.mode(PetDesk.social(deskMode));if(ownerPending){ownerPending=false;conversation.ownerMode(!getSystemService(KeyguardManager.class).isDeviceLocked());wakeWanted=true;resting=false;}stopService(new Intent(this,VoiceService.class));registerReceiver(screenOff,new IntentFilter(Intent.ACTION_SCREEN_OFF),Context.RECEIVER_NOT_EXPORTED);face.resume();appearance();tick.run();if(trackingWanted)startCamera();getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(!permissionRequested&&(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)){permissionRequested=true;requestPermissions(new String[]{Manifest.permission.CAMERA,Manifest.permission.RECORD_AUDIO},196);}else startWake();}
    private void startWake(){if(!visible||!wakeWanted||resting||lowBattery||conversation.running())return;if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){if(!permissionRequested){permissionRequested=true;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},192);}return;}conversation.start(true);}
    @Override protected void onPause(){visible=false;if(activityFeed!=null)activityFeed.clear();game="";reactionAt=0;peekLeftAt=0;main.removeCallbacks(gameReady);latestReply="";directTalking=false;previewPlaying=false;social.mode(PetSocial.Mode.QUIET);dancing=false;conversation.ownerMode(false);if(!ownerAuthenticating&&ownerCancellation!=null)ownerCancellation.cancel();unregisterReceiver(screenOff);answer.setText("");answer.setVisibility(View.GONE);if(coverCaption!=null){coverCaption.setText("");coverCaption.setVisibility(View.GONE);}conversation.stop();musicState.reset();face.music(false,0);stopCamera();face.pause();main.removeCallbacks(tick);lifecycle.handleLifecycleEvent(Lifecycle.Event.ON_PAUSE);super.onPause();}
    @Override protected void onStop(){folding.removeWindowLayoutInfoListener(folds);lifecycle.handleLifecycleEvent(Lifecycle.Event.ON_STOP);super.onStop();}
    @Override protected void onDestroy(){if(ownerCancellation!=null)ownerCancellation.cancel();conversation.close();sharing.close();if(activityFeed!=null)activityFeed.close();if(sheet!=null)sheet.dismiss();main.removeCallbacksAndMessages(null);lifecycle.handleLifecycleEvent(Lifecycle.Event.ON_DESTROY);super.onDestroy();}
    @Override public void onConfigurationChanged(Configuration configuration){super.onConfigurationChanged(configuration);root.post(this::reflow);}
